private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    // Assuming bb points to a byte array containing UTF-8 encoded data
    int b1 = bb.get(i + 0);
    int b2 = bb.get(i + 1);
    int b3 = bb.get(i + 2);
    int b4 = bb.get(i + 3);

    // Calculate the character based on the UTF-8 encoding
    int char1 = (b1 & 0x3F) << 6;
    int char2 = (b2 & 0x3F) << 6;
    int char3 = (b3 & 0x3F) << 6;
    int char4 = (b4 & 0x3F) << 6;
    int char5 = (b4 & 0x3F) >> 2;

    int decodedChar = char1 | char2 | char3 | char4 | char5;

    // Check for UTF-16 surrogate pair
    if ((b1 & 0xE0) == 0xE0) {
        int char6 = bb.get(i + 4);
        if ((b2 & 0xC0) == 0xC0) {
            decodedChar = ((b1 & 0x1F) << 12) | ((b2 & 0x3F) << 6) | (b6 & 0x3F);
        }
    }

    // Append the decoded character to the StringBuilder
    sb.append((char) decodedChar);

    // Move the index to the character after the decoded UTF-8 sequence
    return i + 4;
}
