private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int firstByte = bb.get(i);
    int secondByte = (i + 1 < bb.limit() && bb.get(i + 1) != 0) ? bb.get(i + 1) : 0;
    int thirdByte = (i + 2 < bb.limit() && bb.get(i + 2) != 0) ? bb.get(i + 2) : 0;
    int fourthByte = (i + 3 < bb.limit() && bb.get(i + 3) != 0) ? bb.get(i + 3) : 0;

    // UTF-8 encoding consists of different byte patterns for singleByte, multiByte, and variable-length utf-8 characters
    switch (firstByte >> 4) {
        case 0: // 0b0xxx: single byte, ASCII characters
            sb.append((char) firstByte);
            break;
        case 1: // 0b1xxxx: continuation byte, 110xxxxx x xxxx xxxx
            sb.append((char) ((firstByte & 0x3F) | (secondByte << 6)));
            i += 1;
            break;
        case 2: // 0b10xxxx: continuation byte, 1110xxxx x xxxx xxxx x xxxx xxxx
            sb.append(readQualifiedName(i, bb, firstByte & 0x3F));
            i += 2;
            break;
        case 3: // 0b11xxxx: multi-byte (or variable-length) or tweaked utf-8 character, 1111xxxx x xxxx xxxx x xxxx xxxx
            int length = firstByte & 0x07; // 0b0000, 0b0001 - 0b1011: 1 - 5 bytes, 0b1101 to 0b1111: up to 10 bytes
            int nextByte = i + length;
            char character = readQualifiedName(nextByte, bb, firstByte & 0x3F);
            sb.append(character);
            i = nextByte;
            // Skip additional bytes for utf-8 characters
            if (length > 3) {
                i += length - 3;
            }
            break;
        default: // invalid first byte for UTF-8
            sb.append((char) firstByte); // Arbitrarily append first byte
            break;
    }
    return i;
