    TreeNode<T> parent = node.left;
    // Store the right child of the right child of the node
    TreeNode<T> newChild = parent.right;

    // Replace the left child of the current node with the right child of the left child
    node.left = newChild;

    // Replace the right child of the left child of the current node with the current node
    parent.right = node;

    // Return the new parent of the current node
    return parent;
