public class ClassPathUtil {
    @SuppressWarnings("unchecked")
    public static void addToClassPath(Vector<URL> cpV, String dir) {
        File directory = new File(dir);
        if (!directory.isDirectory()) {
            throw new IllegalArgumentException("The provided directory does not exist or is not a directory.");
        }

        File[] jarFiles = directory.listFiles((dirEntry) -> dirEntry.getName().endsWith(".jar") || dirEntry.getName().endsWith(".JAR"));
        if (jarFiles == null) {
            return;
        }

        for (File jarFile : jarFiles) {
            try {
                cpV.add(jarFile.toURI().toURL());
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }
}
