import java.io.File;
import java.io.IOException;
import java.net.URL;
import java.util.Enumeration;

public static void addToClassPath(Vector<URL> cpV, String dir) {
    File dirFile = new File(dir);
    if (dirFile.isDirectory()) {
        Enumeration<File> files = (Enumeration<File>) dirFile.listFiles((pathname) -> pathname.getName().endsWith(".jar"));
        while (files.hasMoreElements()) {
            File jarFile = files.nextElement();
            try {
                cpV.add(jarFile.toURI().toURL());
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }
}
