    for (int i = end; i < headerPart.length(); i++) {
        if (headerPart.charAt(i) == '\r') {
            int nextChar = i + 1;
            if (nextChar < headerPart.length() && headerPart.charAt(nextChar) == '\n') {
                return i;
            }
        }
    }
    // Return -1 if no \r\n sequence is found after end index
    return -1;
}
