public class IdentityAutomorphism<V,E> extends IsomorphicGraphMapping<V,E> {
    private Map<V,V> isomorphismMap;

    public IdentityAutomorphism(Graph<V,E> graph) {
        this.isomorphismMap = new HashMap<>();
        for (V vertex : graph.getVertices()) {
            this.isomorphismMap.put(vertex, vertex);
        }
    }

    @Override
    public Map<V,V> getIsomorphismMap() {
        return isomorphismMap;
    }

    @Override
    public Set<String> getMappings() {
        Set<String> mappings = new HashSet<>();
        for (Map.Entry<V,V> entry : isomorphismMap.entrySet()) {
            String mapping = entry.getKey().toString() + " -> " + entry.getValue().toString();
            mappings.add(mapping);
        }
        return mappings;
    }

    @Override
    public void apply(Graph<V,E> originalGraph, Graph<V,E> resultGraph) {
        for (Map.Entry<V,V> entry : isomorphismMap.entrySet()) {
            resultGraph.setVertex(entry.getKey(), originalGraph.getVertex(entry.getValue()));
        }
    }
}
