private void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Generate vertices for the bipartite graph
    int numVertexA = 5; // Number of vertices in set A
    int numVertexB = 3; // Number of vertices in set B

    // Create sets A and B
    Set<V> vertexSetA = new HashSet<>();
    Set<V> vertexSetB = new HashSet<>();

    // Populate sets A with vertices
    for (int i = 0; i < numVertexA; i++) {
        V vertex = new V("A" + i);
        vertexSetA.add(vertex);
        resultMap.put("A" + i, vertex);
    }

    // Populate sets B with vertices
    for (int i = 0; i < numVertexB; i++) {
        V vertex = new V("B" + i);
        vertexSetB.add(vertex);
        resultMap.put("B" + i, vertex);
    }

    // Create edges between sets A and B
    for (V vertexA : vertexSetA) {
        for (V vertexB : vertexSetB) {
            // Add edge between vertexA and vertexB
            target.addEdge(vertexA, vertexB);
        }
    }
}
