@Override public void generateGraph(Graph<V,E> target, Map<String, V> resultMap) {
    int numVertices = target.getNumVertices();
    Map<String, V> partitions = createPartitions(numVertices);

    List<V> vertices = target.getVertices();
    for (V vertex : vertices) {
        String partitionKey = partitions.getOrDefault("partition1-" + (vertex.getId() % numVertices / 2), "partition2-" + (vertex.getId() % numVertices / 2));
        resultMap.put(vertex.getId(), partitions.get(partitionKey));
    }
}
