public class GraphGenerator {
    @Override
    public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
        V root = new V();
        linkedHashSet<V> left = new LinkedHashSet<>();
        linkedHashSet<V> right = new LinkedHashSet<>();
        initializeGraph(root, left, right);

        // Construct complete bipartite graph
        for (V vertex : left) {
            for (V neighbor : right) {
                E edge = new E();
                target.addEdge(vertex, neighbor, edge);
            }
        }

        resultMap.put("root", root);
        resultMap.put("left", left);
        resultMap.put("right", right);
    }

    private void initializeGraph(V root, Set<V> left, Set<V> right) {
        left.add(root);
    }
