public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Calculate the length of the message encoded by the schema
    schema.writeSchemaOf(out, message);
    // Get the size of the encoded message
    int length = schema.getMessageSizeOf(out, message);
    // Write the length to the stream as a 2-byte unsigned int
    out.write((length >> 8) & 0xFF);
    out.write(length & 0xFF);
    // Write the encoded message to the stream
    schema.writeMessageTo(out, message, buffer);
    // Return the size of the encoded message
    return length;
}
