public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType pt = (ParameterizedType) genericType;
        Type[] actualTypeArguments = pt.getActualTypeArguments();
        List<Class<?>> classList = new ArrayList<>();

        for (Type actualType : actualTypeArguments) {
            if (actualType instanceof WildcardType) {
                WildcardType wt = (WildcardType) actualType;
                return new Class<?>[]{null};
            } else if (actualType instanceof Class) {
                classList.add((Class<?>) actualType);
            } else if (actualType instanceof TypeVariable) {
                TypeVariable<?> tv = (TypeVariable<?>) actualType;
                if (tv.getGenericDeclaration() instanceof ParameterizedType) {
                    ParameterizedType pt2 = (ParameterizedType) tv.getGenericDeclaration();
                    Type[] tt2 = pt2.getActualTypeArguments();
                    List<Class<?>> classList2 = new ArrayList<>();
                    for (Type tt : tt2) {
                        if (tt instanceof Class) {
                            classList2.add((Class<?>) tt);
                        } else if (tt instanceof TypeVariable) {
                            TypeVariable<?> tv2 = (TypeVariable<?>) tt;
                            if (tv2.getGenericDeclaration() instanceof ParameterizedType) {
                                ParameterizedType pt3 = (ParameterizedType) tv2.getGenericDeclaration();
                                Type[] tt3 = pt3.getActualTypeArguments();
                                for (Type tt4 : tt3) {
                                    if (tt4 instanceof Class) {
                                        classList2.add((Class<?>) tt4);
                                    }
                                }
                            }
                        }
                    if (!classList2.isEmpty()) {
                        classList.addAll(classList2);
                    }
                }
            }
        }

        return classList.toArray(new Class<?>[classList.size()]);
    }
    return null;
}
