public Mappings diffStructure(String tableName, Mappings mappings) {
    if(mappings == null) return null;

    Mappings diffMap = new Mappings();
    for(String indexName : mappings.getIndexNames().keySet()) {
        if(!tableName.equals(indexName)) {
            Mappings indexDiff = buildIndexDiff(mappings, indexName);
            if(indexDiff != null) {
                diffMap.put(indexName, indexDiff);
            }
        }
    }
    return diffMap;
}

private Mappings buildIndexDiff(Mappings sourceMappings, String indexName) {
    if(sourceMappings == null) return null;

    Mappings diffMap = new Mappings();

    Mapping.Builder indexBuilder = sourceMappings.getIndex(indexName);
    if(indexBuilder.isExists()) {
        Mapping indexMapping = indexBuilder.getMapping();

        for(String typeName : indexMapping.getTypeNames()) {
            TypeMappings typeMappings = indexMapping.getType(typeName);
            if(typeMappings.isExists()) {
                TypeMapping typeMapping = typeMappings.getMapping();

                for(Fields fields : typeMapping.getFields()) {
                    for(Field field : fields.getFields()) {
                        boolean fieldExists = false;
                        for(String fieldName : sourceMappings.getIndex(indexName).getType(typeName).getFieldNames()) {
                            if(fieldName.equals(field.getName())) {
                                fieldExists = true;
                                break;
                            }
                        }
                        if(!fieldExists) {
                            Field newField = new Field(
                                    field.getName(),
                                    field.getType(),
                                    field.store(),
                                    field.analyzer(),
                                    field.indexOptions(),
                                    field.docValues()
                            );
                            diffMap.getIndex(indexName).getType(typeName).addField(newField);
                        }
                    }
                }
            }
        }
    }

    return diffMap;
}
