    Mappings diffMappings = new Mappings();

    // Iterate through the input mappings for each field
    Map<String, Mappings.Field> fields = mappings.fields();
    for (Map.Entry<String, Mappings.Field> entry : fields.entrySet()) {
        String fieldName = entry.getKey();
        Mappings.Field inputField = entry.getValue();

        // Check if the field does not exist in the output mappings
        if (!outputMappings.fields().containsKey(fieldName)) {
            // If the field does not exist, add it to the diff mappings
            Mappings.Field diffField = new Mappings.Field(inputField);
            diffMappings.addField(fieldName, diffField);
        } else {
            // If the field exists in the output mappings, check its configuration
            Mappings.Field outputField = outputMappings.fields().get(fieldName);

            // Compare the input and output fields to see if they differ
            if (!inputField.equals(outputField)) {
                // If the fields differ, add them to the diff mappings with the same configuration
                Mappings.Field diffField = new Mappings.Field(inputField);
                diffField.config(outputField.config());
                diffMappings.addField(fieldName, diffField);
            }
        }
    }

    return diffMappings;
}
