    Mappings diffMappings = new Mappings();

    // Perform a search for fields in theMappings that do not exist in the current mapping
    SearchSourceBuilder searchSourceBuilder = new SearchSourceBuilder();
    searchSourceBuilder.query(QueryBuilders.matchAllQuery());
    searchSourceBuilder.aggregation(AggregationBuilders.cardinality("non existents"));

    SearchRequest searchRequest = new SearchRequest(tableName);
    searchRequest.source(searchSourceBuilder);

    try (RestClient restClient = RestClient.builder(new HttpHost("localhost", 9200, "http")).build()) {
        SearchResponse searchResponse = restClient.performRequest(searchRequest);

        if (searchResponse.getAggregations() != null) {
            CardinalityAggregationBuilder cardinalityAggregation = (CardinalityAggregationBuilder) searchResponse.getAggregations().get("non existents");
            long nonExistentCount = cardinalityAggregation.getValue();

            if (nonExistentCount > 0) {
                // Find the Schema where these fields do not exist and add them to the diffMappings
                for (ArrayElement mapping : mappings.mappingsArray()) {
