private static long maxDay = 86400000; // 1 day in milliseconds
private static long halfDay = maxDay / 2;
static int daysInHalfDay = 14;
static int daysInFullDay = 28;

private static int f2h(long timeBucket) {
    return (int) timeBucket / halfDay; // <halfDay_BUCKET_INDEX>
}

private static int h2f(long timeBucket) {
    return (int) (timeBucket % halfDay) / daysInHalfDay; // <FULL_DAY_BUCKET_INDEX>
}

private static int oneDayInOneBucket(long timeBucket) {
    return (int) (timeBucket - maxDay * f2h(timeBucket)); // <FULL_DAY_LIFE>
}

private static int baseDayOfHalfDay(int dayIndex) {
    return (int) Math.ceil(((double) dayIndex) * halfDay + 1 / 2); // <BASE_DAY_OF_HALF_DAY_INDEX>
}

private static int baseDayOfFullDay(int dayIndex) {
    return (int) Math.ceil(((double) (dayIndex * daysInHalfDay)) + 1 / 2); // <BASE_DAY_OF_FULL_DAY_INDEX>
}

private static long compressTimeBucket(long timeBucket, int dayStep) {
    int fullDayIndex = f2h(timeBucket);
    int halfDayIndex = h2f(timeBucket);
    int oneDayBucket = oneDayInOneBucket(timeBucket);
    long maxDayTime = baseDayOfFullDay(fullDayIndex) * 2 * maxDay + baseDayOfHalfDay(halfDayIndex) * halfDay + oneDayBucket;
    long baseTime = maxDayTime + baseDayOfHalfDay(halfDayIndex) * halfDay;
    return baseTime - timeBucket;
}
