public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = len; // Start with the length specified in the method parameters
    int currentIndex = index;

    while (size > 0 && currentIndex < str.length()) {
        // Extract the byte at the current index
        byte b = (byte) str.charAt(currentIndex);
        currentIndex++;

        // Check the first bit (7th bit can be used to check UTF-8 encoding)
        if ((b & 0x80) == 0x00) {
            size--; // Single-byte character, decrease size
        } else if ((b & 0xE0) == 0xC0) {
            if (currentIndex >= str.length()) {
                throw new IllegalArgumentException("Incomplete character");
            }
            size -= 2; // Two-byte character, decrease size with leading byte
        } else if ((b & 0xF0) == 0xE0) {
            if (currentIndex + 1 >= str.length()) {
                throw new IllegalArgumentException("Incomplete character");
            }
            size -= 3; // Three-byte character, decrease size with leading two bytes
        } else if ((b & 0xF8) == 0xF0) {
            if (currentIndex + 2 >= str.length()) {
                throw new IllegalArgumentException("Incomplete character");
            }
            size -= 4; // Four-byte character, decrease size with leading three bytes
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 start byte");
        }
    }

    return size;
}
