public static int computeUTF8Size(CharSequence str, int index, int len) {
  if (str == null || index < 0 || len <= 0 || index + len > str.length()) {
    throw new IllegalArgumentException();
  }
  int start = index;
  int size = 0;
  while (len > 0) {
    int remaining = len;
    int highBit = str.charAt(start);
    if (highBit >= 0b1100_0000) {
      if (highBit < 0b1101_0000) { // 1100_0000...1100_1111
        if (higher & 0b0000_0111 == 0) { // 1101_...1101_00..
          size += 4;
          start += 4;
        } else { // 1101_...1101_10..
          size += 3;
          start += 3;
        }
      } else { // 1101_0001...1101_11.. // 2nd set of continuation bits
        size += 2;
        start += 2;
        remaining -= 2;
      }
    } else if (highBit >= 0b1000_0000) {
      if (highBit < 0b1001_0000) { // 1000_...1000_11..
        size += 3;
        start += 3;
        remaining -= 3;
      } else { // 1001_0001...1001_11.. // 3rd set of continuation bits
        size += 2;
        start += 2;
        remaining -= 2;
      }
    } else { // highBit < 0b1000_0000 // not the start of a utf8 sequence
      break;
    }
    len = remaining;
  }
  return size;
}
