import java.util.ArrayList;
import java.util.List;
import javax.servlet.UriComponents;
import javax.servlet.http.HttpServletResponse;
import java.net.URI;

public class UriSegmentDecoder {
    public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        List<PathSegmentImpl> pathSegments = new ArrayList<>();

        if (!u.isAbsolute()) {
            return pathSegments; // No slashes to decode, simply return an empty list.
        }

        UriComponents components = UriComponents.parse(u.toString());
        String path = components.getPath();

        if (decode) {
            path = path.substring(1).split("/");
        } else {
            path = path.substring(1).split("/");
        }

        for (int i = 0; i < path.length; i++) {
            if (path[i].isEmpty()) {
                continue; // Skip empty strings if decode is true.
            }
            if (decode) {
                path[i] = UriComponents.decode(path[i]);
            }
            pathSegments.add(new PathSegmentImpl(path[i]));
        }

        return pathSegments;
    }
}
