import java.util.ArrayList;
import java.util.List;

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    if (!u.isAbsolute() || u.getPath().startsWith("/")) {
        // Trim leading '/' if present and consider it as a delimiter
        u = new URI(u.toString().replaceFirst("^/", ""));
    }

    // Split the path into segments
    String[] pathComponents = u.getPath().split("/");
    for (String component : pathComponents) {
        pathSegments.add(PathSegmentImpl.valueOf(component, decode));
    }

    return pathSegments;
}
