public long readRawVarint64() throws IOException {
    long value = 0;
    int shift = 0;

    while ((byte) read() >= 0) {
        int byteValue = (byte) read();

        if ((byteValue & 128) == 0) {
            value |= (byteValue << shift);
            break;
        }

        byteValue &= ~128;

        value |= (byteValue << shift);
        shift += 7;
    }

    return value;
}
