private Map<V, Set<E>> index = new HashMap<>();

protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    Set<E> edges = index.getOrDefault(sourceVertex, new HashSet<>());
    edges.add(e);
    index.put(sourceVertex, edges);
    // Ensure the target vertex's incident edges are added as well
    if (index.containsKey(targetVertex)) {
        edges = index.get(targetVertex);
        edges.add(e);
        index.put(targetVertex, edges);
    } else {
        Set<E> newEdges = new HashSet<>();
        newEdges.add(e);
        index.put(targetVertex, newEdges);
    }
}
