@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type != Character.class) {
        throw new IllegalArgumentException("Invalid type conversion. Expected Character, got " + type.getName());
    }
    if (value == null) {
        return null;
    }
    if (!(value instanceof String)) {
        throw new IllegalArgumentException("Value must be a String. Got: " + value.getClass().getName());
    }
    String stringValue = (String) value;
    if (stringValue.length() != 1) {
        throw new IllegalArgumentException("String must be exactly one character long. Got: " + stringValue.length());
    }
    return stringValue.charAt(0);
}
