public Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (Character.class.isAssignableFrom(type)) {
        if (value instanceof String) {
            return ((String) value).charAt(0);
        } else if (value instanceof Integer) {
            return (char) ((Integer) value);
        } else if (value instanceof Short) {
            return (char) ((Short) value);
        } else {
            throw new IllegalArgumentException("Unsupported type for conversion: " + type);
        }
    } else {
        throw new IllegalArgumentException("Invalid type for conversion: " + type);
    }
}
