public static int nextPrime(int desiredCapacity){
    int primes[] = { 2, 3, 5, 7, 11, 13 };
    for (int i = 0; i < primes.length; i++) {
        if (desiredCapacity > primes[i] && desiredCapacity < 1000) {
            return primes[i] + 7;
        }
    }
    double cap = Math.ceil(desiredCapacity / 1.1);
    boolean found = false;
    for (int i = 1; i <cap; i++) {
        double root = Math.sqrt(i);
        found = false;
        for (int j = 0; j < primes.length; j++) {
            if (i % primes[j] == 0) {
                found = true;
                break;
            }
        }
        if (!found && root == Math.floor(root)) {
            return i;
        }
    }
    return -1; // This should not happen
