public static String unescapeJava(String str) throws Exception {
    StringBuilder result = new StringBuilder(str);
    int length = result.length();
    StringBuilder pattern = new StringBuilder();

    for (int i = 0; i < length; i++) {
        char c = result.charAt(i);
        if (c == '\\' && i + 1 < length) {
            char next = result.charAt(i + 1);
            if (next == '\\') {
                result.setCharAt(i, '\\');
                pattern.setLength(0);
                i++; // Skip the next character
            } else if (next == 't') {
                result.setCharAt(i, '\t');
                pattern.setLength(0);
                i++; // Skip the next character
            } else if (next == 'b') {
                result.setCharAt(i, '\b');
                pattern.setLength(0);
                i++; // Skip the next character
            } else if (next == 'n') {
                result.setCharAt(i, '\n');
                pattern.setLength(0);
                i++; // Skip the next character
            } else if (next == 'f') {
                result.setCharAt(i, '\f');
                pattern.setLength(0);
                i++; // Skip the next character
            } else if (next == 'r') {
                result.setCharAt(i, '\r');
                pattern.setLength(0);
                i++; // Skip the next character
            } else if (next == '"') {
                result.setCharAt(i, '"');
                pattern.setLength(0);
                i++; // Skip the next character
            } else if ( Character.isLetterOrDigit(next) ) {
                pattern.append(next);
            } else {
                pattern.setLength(0); // This character has a special meaning
                if (i > 0 && result.charAt(i - 1) == '\\') {
                    pattern.append(next); // Append the special character
                } else {
                    // Skip the special character
                    i++;
                }
            }
        } else {
            pattern.setLength(0);
        }
    }

    return result.toString();
}
