        switch (ch) {
            case '\\':
                escape++;
                arr[j++] = ch;
                if (escape > 1) { // More than one backslash means normal escape
                    arr[j++] = str.charAt(i + 1);
                    escape--;
                }
                break;
            default:
                arr[j++] = ch;
                escape = 0;
                break;
