        if (ch == '\\' && i + 1 < len && chars[i + 1] == '\\') {
            unescapedStr.append(chars[i + 1]);
            i++; // Skip the next character as它 is escaped
        } else if ((ch == '\'' && utf8Next(chars, i) == '\n') || (ch == '"' && utf8Next(chars, i) == '\n')) {
            unescapedStr.append(ch);
            unescapedStr.append(utf8Next(chars, i));
            i++; // Skip the newline character
        } else {
            unescapedStr.append(ch);
        }
    }
    return unescapedStr.toString();
}

private static boolean utf8Next(char[] chars, int idx) {
    return (idx + 1) < chars.length && (chars[idx] & 240) == 224; // Check if the next byte starts a multibyte sequence
