private static final int UTF8 = 1;

public final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    int shift = 0;
    int index = constantPoolEntryIndex;
    while ((byte) (byteBuffer[index] >> shift) == 0x80) {
        index++;
        shift += 7;
    }
    // read length using 16 bits
    int length = ((charBuffer[index] << 8) & 0xff) | ((charBuffer[index + 1] & 0xff) << 0);
    // read UTF-8 characters
    for (int i = 0; i < length; i++) {
        index++;
        if ((byte) (byteBuffer[index] >> 4) == 0x80) {
            // multi-byte character
            char wchar = 0;
            wchar |= ((charBuffer[index] & 0x3F) << 6);
            wchar |= (charBuffer[index + 1] & 0xFF) << 0;
            index += 2;
            charBuffer[i] = wchar;
        } else {
            // single-byte character
            charBuffer[i] = (charBuffer[index] & 0xFF);
            index++;
        }
    }
    return new String(charBuffer);
}
