    charBuffer[0] = '\0'; // Append a null terminator to mark the end of the string
    for (int i = 1, pos = 0; i <= stringLength; i++) {
        int index = readV16(constantPoolEntryIndex + i + 1); // Read the index of the UTF-8 encoded string
        char[] str = readUtf8(constantPoolEntryIndex + index + 1, charBuffer, String.valueOf(constantPoolEntryIndex + index + 1));
        System.arraycopy(str, 0, charBuffer, pos, str.length);
