private String unescapeId(String input) {
    StringBuilder sb = new StringBuilder();
    int i = 0;
    while (i < input.length()) {
        char c = input.charAt(i);
        if (c == '\\') {
            i++;
            if (i >= input.length()) {
                throw new IllegalArgumentException("Invalid escape sequence");
            }
            char ch = input.charAt(i);
            switch (ch) {
                case 'n':
                    sb.append('\n');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case '"':
                    sb.append('"');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                default:
                    sb.append(ch);
                    break;
            }
        } else {
            sb.append(c);
        }
        i++;
    }
    return sb.toString();
}
