private String unescapeId(String input) {
    StringBuilder escapedId = new StringBuilder(input.length());
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            i++;
            char nextChar = input.charAt(i);
            switch (nextChar) {
                case 'b':
                    escapedId.append('\b');
                    break;
                case 'f':
                    escapedId.append('\f');
                    break;
                case 'n':
                    escapedId.append('\n');
                    break;
                case 't':
                    escapedId.append('\t');
                    break;
                case 'r':
                    escapedId.append('\r');
                    break;
                case '\\':
                    escapedId.append('\\');
                    break;
                default:
                   escapedId.append(nextChar);
                    break;
            }
        } else {
            escapedId.append(c);
        }
    }
    return escapedId.toString();
}
