private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    Set<Integer> emptyBucketLabel = new HashSet<>();
    emptyBucketLabel.add(0);

    bucketsByLabel.get(minLabel).clear();
    for (int vertex : labels) {
        if (!bucketsByLabel.get(vertex).isEmpty()) {
            bucketsByLabel.get(vertex).remove(minLabel);
            bucketsByLabel.get(0).add(vertex);
        }
    }

    labels.clear();
    for (int vertex : emptyBucketLabel) {
        labels.add(vertex);
    }
}
