private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Create an empty list to store vertices with label 0
    List<Set<Integer>> bucketsByLabelForClear = new ArrayList<>();

    // Iterate through the buckets and move vertices with the current minimum label to bucket 0
    for (int i = 0; i < bucketsByLabel.size(); i++) {
        if (bucketsByLabel.get(i).size() > 0 && bucketsByLabel.get(i).iterator().next() == minLabel) {
            bucketByLabelForClear.add(bucketsByLabel.get(i));
            bucketsByLabel.set(i, new HashSet<>());
        }
    }

    // Remove the empty buckets from the list
    bucketsByLabel.removeAll(bucketByLabelForClear);

    // Assign the new labels
    for (int i = 0; i < bucketsByLabel.size(); i++) {
        if (bucketsByLabel.get(i).size() > 0) {
            bucketsByLabel.get(i).iterator().forEachRemaining(vertex -> labels.set(vertex, i));
        }
    }
}
