boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return true;
    }

    // Check if the node is the head of the list
    if (head == node) {
        head = node.getNext();
        return true;
    }

    // Check if the node is the tail of the list
    if (tail == node) {
        tail = node.getPrev();
        tail.setNext(null);
        return true;
    }

    // If the node is in the middle of the list
    ListNodeImpl<E> prevNode = node.getPrev();
    prevNode.setNext(node.getNext());
    node.getNext().setPrev(prevNode);
    return true;
}
