public static String base64Decode(final String s) throws IllegalArgumentException {
    if (s == null || s.isEmpty()) {
        throw new IllegalArgumentException("Input string cannot be null or empty");
    }

    int len = s.length();
    int i = 0;
    StringBuilder sb = new StringBuilder(len / 4);
    int high, low;

    while (i < len) {
        high = s.charAt(i++) & 0xff;
        if (i == len) {
            sb.append((char) (high >> 2));
            if (high & 0x3) {
                sb.append((char) (((high & 0x3) << 4) | (s.charAt(i) & 0xff) >> 4));
                sb.append((char) (((s.charAt(i) & 0x3)) << 2));
            }
            break;
        }
        low = s.charAt(i++) & 0xff;
        sb.append((char) (((high >> 2) << 6) | (low & 0xff) >> 2));
        if (i == len) break;
        low = s.charAt(i++) & 0xff;
        sb.append((char) (low << 4));
    }

    return sb.toString();
}
