protected static final String BASE64_PATTERN = "[A-Za-z0-9+/]+={0,2}";
private static final int ENCODED_LEN = 4;
private static final int ENCODED_QUOTE_CHAR = '+';
private static final int ENCODED_SPACE_CHAR = ' ';


public static String base64Decode(final String s) {
    // Ensure the input string is base64 encoded
    if (!matches(BASE64_PATTERN)) {
        throw new IllegalArgumentException("Invalid input: " + s);
    }

    int length = s.length();
    StringBuilder sb = new StringBuilder(length / ENCODED_LEN * 3);
    int expectQuote = 0;
    int expectSpace = 0;
    for (int i = 0; i < length; i++) {
        char c = s.charAt(i);
        if (c == ENCODED_QUOTE_CHAR) {
            expectQuote++;
        } else if (c == ENCODED_SPACE_CHAR) {
            expectSpace++;
        } else if (isHexDigit(c)) {
            sb.append(c);
        }
    }
    if ((expectQuote & 1) == 1) {
        if ((expectSpace & 2) == 0) {
            sb.append(ENCODED_QUOTE_CHAR);
        } else {
            throw new IllegalArgumentException("Invalid input: " + s);
        }
    } else if ((expectSpace & 2) == 2) {
        if ((expectQuote & 1) == 1) {
            sb.append(ENCODED_SPACE_CHAR);
        } else {
            throw new IllegalArgumentException("Invalid input: " + s);
        }
    }
    return sb.toString();
}

private static boolean matches(final String pattern) {
    return pattern != null && pattern.matches(BASE64_PATTERN);
}

private static boolean isHexDigit(char c) {
    return c >= '0' && c <= '9' || c >= 'A' && c <= 'F' || c >= 'a' && c <= 'f';
}
