        List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();
        for (Pair<Integer, Integer> edge : edges) {
            Set<Integer> separatorVertices = edge.get(0).intersection(edge.get(1));
            List<Pair<Integer, Integer>> separators = new ArrayList<>();
            for (int vertex : separatorVertices) {
                Pair<Integer, Integer> separator = new Pair<>(vertex, separatorVertices);
                separators.add(separator);
            }
            globalSeparatorList.add(new Pair<>(separators, edge.get(2)));
        }
        return globalSeparatorList;
    }
}
