public ByteVector putInt(final int intValue) {
    if (intValue == 0) {
        return putInt(0);
    }

    byte[] data = new byte[Math.ceil(Math.log(intValue + 1) / Math.log(256))];
    int index = 0;

    while (intValue > 0) {
        data[index++] = (byte) (intValue & 0xFF);
        intValue >>= 8;
    }

    if (index != 0) {
        byte[] temp = new byte[index];
        System.arraycopy(data, 0, temp, index - temp.length, temp.length);
        data = temp;
    }

    this.data = data;

    if (intValue == 0) {
        this.data[0] &= 0xFE;  // Remove high bit to set to negative zero
    }

    return this;
}
