private static <V,E> boolean isCliqueHelper(Graph<V,E> graph, Set<V> vertices, boolean[] marked){
    if (vertices.isEmpty()) return true;
    // find the vertex with the minimum in-degree
    V minVertex = vertices.stream().min(Comparator.comparingInt(id -> {
        int degree = 0;
        for (V neighbor : graph.neighbors(id)) {
            if (vertices.contains(neighbor)) degree++;
        }
        return degree;
    })).orElse(null);
    if (minVertex == null) return false;
    marked[minVertex.hashCode()] = true;
    // check if the minimum vertex is connected to all other vertices in the subgraph
    boolean connected = true;
    for (V neighbor : graph.neighbors(minVertex)) {
        if (!marked[neighbor.hashCode()]) connected = false;
    }
    if (!connected) return false;
    // remove the minimum vertex from the subgraph and try to form a clique
    Set<V> newVertices = new HashSet<>(vertices);
    newVertices.remove(minVertex);
    return isCliqueHelper(graph, newVertices, marked);
}
