import org.graphlib.Graph;

import java.util.HashSet;
import java.util.Set;

/**
 * Check whether the subgraph of <code>graph</code> induced by the given <code>vertices</code> is complete, i.e. a clique.
 * @param graph the graph.
 * @param vertices the vertices to induce the subgraph from.
 * @return true if the induced subgraph is a clique.
 */
private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // Use a set to store the edges of the induced subgraph
    Set<E> inducedEdges = new HashSet<>();

    // Generate the induced subgraph
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1 != v2 && graph.containsEdge(v1, v2)) {
                inducedEdges.add(graph.createEdge(v1, v2));
            }
        }
    }

    // Check if the induced subgraph is a clique
    for (V vertex : vertices) {
        if (inducedEdges.size() != vertices.size() - 1) {
            return false;
        }

        Set<E> vertexEdges = new HashSet<>();
        for (E edge : inducedEdges) {
            if (edge.v1 == vertex) {
                vertexEdges.add(edge);
            }
        }

        if (vertexEdges.size() != vertices.size() - 1) {
            return false;
        }
    }

    return true;
}
