private static <V,E>boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices.isEmpty()) return true; // An empty set is trivially a clique
    if (graph.vertexSet().size() == vertices.size()) return true; // A complete induced subgraph has all vertices connected to each other

    Set<V> inducedVertices = new HashSet<>(vertices);
    List<List<E>> adjacencyLists = new ArrayList<>();

    // Generate adjacency lists for the induced subgraph
    for (V u : inducedVertices) {
        List<E> adj = new ArrayList<>();
        for (V v : inducedVertices) {
            if (u.equals(v)) continue; // Diagonal elements are not included
            if (graph.adj(edge(u, v))) {
                adj.add(edge(u, v));
            }
        }
        adjacencyLists.add(adj);
    }

    // Check if there are any isolated vertices (not connected to any other vertices)
    for (V u : inducedVertices) {
        if (adjacencyLists.stream().noneMatch(adjList -> adjList.contains(edge(u, u)))) {
            return false;
        }
    }

    return true;
}
