public static String applyRelativePath(String path, String relativePath) {
    if (path == null || path.isEmpty()) {
        return relativePath; // Return relative path if path is null or empty
    }

    StringBuilder sb = new StringBuilder(path);

    int rootIndex = sb.indexOf("/");

    if (rootIndex == -1) {
        sb.append("/"); // Add slash if root is not found
    }

    int relativePathIndex = relativePath.indexOf("/");

    if (relativePathIndex == 0) {
        relativePath = relativePath.substring(1); // Remove leading slash if present
    }

    sb.append(relativePath);

    return sb.toString();
}
