public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    long startMs = -1, endMs = -1;

    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        if (timeRange.getTime() > startMs) {
            startMs = timeRange.getTime();
        }
        if (timeRange.getTime() < endMs) {
            endMs = timeRange.getTime();
        }
    }

    if (startMs == -1 || endMs == -1) {
        throw new IllegalArgumentException("Invalid time range");
    }

    // Load data from file within the specified time range
    long lastModified = file.lastModified();
    while (lastModified <= endMs) {
        ThreadSnapshot snapshot = loadSnapshot(file, lastModified);
        threadSnapshots.add(snapshot);

        // Get the next loaded file
        File nextFile = getLatestFile(lastModified);
        if (nextFile == null) {
            break;
        }
        lastModified = nextFile.lastModified();
    }

    return threadSnapshots;
}
